const { ref, computed } = require('vue');

function createCounter(initial) {
  const count = ref(initial || 0);
  let multiplier = 2; // BUG: plain variable, not reactive - computed won't track it

  const doubled = computed(() => count.value * multiplier);

  function setMultiplier(m) {
    multiplier = m;
  }

  return { count, doubled, setMultiplier };
}

module.exports = { createCounter };

test_setup_files.test_computed.js:
const assert = require('assert');
const { createCounter } = require('./counter.js');

const c = createCounter(5);
assert.strictEqual(c.doubled.value, 10, `expected initial doubled 10, got ${c.doubled.value}`);

c.setMultiplier(3);
assert.strictEqual(c.doubled.value, 15, `expected doubled to recompute to 15 after setMultiplier(3), got ${c.doubled.value}`);

c.setMultiplier(1);
assert.strictEqual(c.doubled.value, 5, `expected doubled to recompute to 5 after setMultiplier(1), got ${c.doubled.value}`);

c.count.value = 10;
assert.strictEqual(c.doubled.value, 10, `expected doubled 10 after count changes to 10 with multiplier 1, got ${c.doubled.value}`);

c.setMultiplier(4);
assert.strictEqual(c.doubled.value, 40, `expected doubled 40 after setMultiplier(4) with count 10, got ${c.doubled.value}`);

